package org.hyperledger.besu.crypto;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertInstanceOf;
import static java.nio.charset.StandardCharsets.UTF_8;

import java.security.PrivateKey;

import org.apache.tuweni.bytes.Bytes;
import org.bouncycastle.pqc.crypto.mldsa.MLDSAParameters;
import org.bouncycastle.pqc.crypto.mldsa.MLDSAPrivateKeyParameters;
import org.hyperledger.besu.crypto.algorithms.parameters.DSAParametersSet;
import org.hyperledger.besu.crypto.key.types.MLDSAPrivateKey;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.EnumSource;

class MLDSAPrivateKeyTest {
    private static String expectedPrivateKeyMLDSA44;
    private static String expectedPrivateKeyMLDSA65;
    private static String expectedPrivateKeyMLDSA87;
    private static String seedString;

    @BeforeAll
    static void setUp(){
        expectedPrivateKeyMLDSA44 = getPrivateKeyMLDSA44();
        expectedPrivateKeyMLDSA65 = getPrivateKeyMLDSA65();
        expectedPrivateKeyMLDSA87 = getPrivateKeyMLDSA87();
        seedString = "298a61befdd243eb443e2b3ca27a92fb3fcfc6d88ff089e24eee75610d2b5efc";
    }

    @ParameterizedTest
    @EnumSource(value = DSAParametersSet.class, names = {"MLDSA44", "MLDSA65", "MLDSA87"})
    void derivePrivateKeyFromSeed(final DSAParametersSet params) { 
        Bytes seedBytes = Bytes.fromHexString(seedString);

        MLDSAPrivateKey privateKey = MLDSAPrivateKey.create(seedBytes, params);

        assertNotNull(privateKey);
        assertEquals(params.getName(), privateKey.getAlgorithm());
        assertEquals("RAW", privateKey.getFormat());
        assertTrue(privateKey.getEncoded().length > 0);

        String actualString = bytesToHex(privateKey.getEncoded());

        switch (params) {
            case MLDSA44:
                assertEquals(expectedPrivateKeyMLDSA44, actualString);
                break;
            case MLDSA65:
                assertEquals(expectedPrivateKeyMLDSA65, actualString);
                break;
            case MLDSA87:
                assertEquals(expectedPrivateKeyMLDSA87, actualString);
                break;
            default:
                break;
        }
    }

    @ParameterizedTest
    @EnumSource(value = DSAParametersSet.class, names = {"MLDSA44", "MLDSA65", "MLDSA87"})
    void createPrivateKeyFromExpandedSk(final DSAParametersSet params) {
        switch (params) {
            case MLDSA44:
                MLDSAPrivateKey privateKeyMLDSA44 = MLDSAPrivateKey.create(Bytes.fromHexString(expectedPrivateKeyMLDSA44), params);
                String skMLDSA44 = bytesToHex(privateKeyMLDSA44.getEncoded());
                assertEquals(expectedPrivateKeyMLDSA44, skMLDSA44);
                break;
            case MLDSA65:
                MLDSAPrivateKey privateKeyMLDSA65 = MLDSAPrivateKey.create(Bytes.fromHexString(expectedPrivateKeyMLDSA65), params);
                String skMLDSA65 = bytesToHex(privateKeyMLDSA65.getEncoded());
                assertEquals(expectedPrivateKeyMLDSA65, skMLDSA65);
                break;
            case MLDSA87:
                MLDSAPrivateKey privateKeyMLDSA87 = MLDSAPrivateKey.create(Bytes.fromHexString(expectedPrivateKeyMLDSA87), params);
                String skMLDSA87 = bytesToHex(privateKeyMLDSA87.getEncoded());
                assertEquals(expectedPrivateKeyMLDSA87, skMLDSA87);
                break;
            default:
                break;
        }
    }

    @ParameterizedTest
    @EnumSource(value = DSAParametersSet.class, names = {"MLDSA44", "MLDSA65", "MLDSA87"})
    void MLDSAPrivateKeyAttributes(final DSAParametersSet params) {
        byte[] originalBytes = "encoded data".getBytes(UTF_8);
        Bytes bytesWrapped = Bytes.wrap(originalBytes);

        PrivateKey privateKey = MLDSAPrivateKey.create(bytesWrapped, params);

        assertEquals(params.getName(), privateKey.getAlgorithm());

        assertEquals("RAW", privateKey.getFormat());

        byte[] encodedBytes = privateKey.getEncoded();
        assertNotNull(encodedBytes);
        assertArrayEquals(originalBytes, encodedBytes);
    }

    private String bytesToHex(final byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    private static String getPrivateKeyMLDSA44(){
        return "";
    }

    private static String getPrivateKeyMLDSA65(){
        return "";
    }

    private static String getPrivateKeyMLDSA87(){
        return "";
    }
}